{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx integration add",
    "description": "Add one working contribution to an integration package",
    "usage": "astryx integration add [options] <kind> <name>",
    "options": [
      {
        "flags": "--dry-run",
        "description": "Validate and show planned writes without changing files"
      },
      {
        "flags": "--type <type>",
        "description": "Template type: page (default) or block; only valid for template"
      },
      {
        "flags": "--replaces <topic>",
        "description": "Existing doc topic this one replaces (letters, digits, _ and -); only valid for doc and not with --extends"
      },
      {
        "flags": "--extends <topic>",
        "description": "Existing doc topic this one extends (letters, digits, _ and -); only valid for doc and not with --replaces"
      },
      {
        "flags": "--parent <namespace>",
        "description": "Namespace of this package to place the doc in, as a guide in its `guides` slot; writes the namespace doc when it is missing, and declares the CLI that reads it as an optional `@astryxdesign/cli` peer. Only valid for doc, and not with --replaces or --extends"
      },
      {
        "flags": "--from <theme>",
        "description": "Existing theme slug to fork as a starting point instead of a blank scaffold; the new theme copies the base and has no link back, and package.json `dependencies` gains the npm packages the copied files import (other than Core and React). Only valid for theme"
      },
      {
        "flags": "--to <version>",
        "description": "Exact semver of the @astryxdesign/core version whose upgrade runs the codemod (e.g. 0.7.0); required for codemod and only valid there"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
